public static final <V> void swap(V[] arr, int i, int j) {
    if (arr == null) {
        throw new IllegalArgumentException("Array must not be null");
    }
    int len = arr.length;
    if (i < 0 || j < 0 || i >= len || j >= len) {
        throw new IndexOutOfBoundsException("Index out of bounds: i=" + i + ", j=" + j + ", length=" + len);
    }
    if (i == j) {
        return;
    }
    V temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}

